('g3-science-adv-f70ad352e331', 3, 'science', 'forces', 'science-reasoning', 'mcq', 5, 'friction', 'It is easier to ride a bike on a road than on grass because grass has more ___.', null, '["light","air","friction","water"]', '{"text":"friction","index":2}', 'Cỏ tạo MA SÁT (friction) lớn hơn mặt đường nên đạp xe nặng hơn. Ma sát là lực cản chuyển động.', 'Hiểu ma sát qua ví dụ thực tế.', '{"grade":3,"coreTopic":"friction","moetSubject":"Science","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '6935af407eb7c1ae', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null)
